sys_ws_operation.operation_script:
(function process(/*RESTRequest*/ request, /*RESTResponse*/ response) {
    var requestBody = request.body.data;

    // 1. Safely handle JSON payload whether sent as Object or Raw String
    if (typeof requestBody === 'string') {
        try {
            requestBody = JSON.parse(requestBody);
        } catch (e) {
            gs.error("[DEBUG - Password Update] JSON Parse Exception: " + e.message);
        }
    }

    // Fallback if requestBody is empty
    requestBody = requestBody || {};

    var stagingSysId = requestBody.staging_sys_id;
    var newPassword = requestBody.password;

    gs.info("[DEBUG - Password Update] Request received for Staging Sys ID: " + stagingSysId);

    // 2. Validate input parameters
    if (!stagingSysId || !newPassword) {
        gs.error("[DEBUG - Password Update] FAILED: Missing staging_sys_id or password in request payload.");
        response.setStatus(400);
        return {
            success: false,
            message: "Missing staging_sys_id or password in request payload."
        };
    }

    // 3. Query the custom registration table
    var stagingGr = new GlideRecord('x_travel_buddy_app_user_password_registration');

    if (stagingGr.get(stagingSysId)) {

        // 4. Save password and update status to trigger Flow Designer
        stagingGr.setValue('u_password', String(newPassword));
        stagingGr.setValue('u_status', 'Pending'); // Triggers Flow

        // Update DB record
        var updatedSysId = stagingGr.update();

        if (updatedSysId) {
            gs.info("[DEBUG - Password Update] SUCCESS: Updated password for User: " + stagingGr.getValue('u_email') + " (Sys ID: " + updatedSysId + ")");
            response.setStatus(200);
            return {
                success: true,
                message: "Password stored successfully in staging table for user: " + stagingGr.getValue('u_email')
            };
        } else {
            gs.error("[DEBUG - Password Update] FAILED: stagingGr.update() returned null for Sys ID: " + stagingSysId);
            response.setStatus(500);
            return {
                success: false,
                message: "Failed to update record in database (ACL or Cross-Scope restriction)."
            };
        }

    } else {
        gs.error("[DEBUG - Password Update] FAILED: Record not found in staging table with Sys ID: " + stagingSysId);
        response.setStatus(404);
        return {
            success: false,
            message: "Staging record not found for ID: " + stagingSysId
        };
    }

})(request, response);
